    public Task<dynamic> DashboardAsync(CancellationToken ct) => One("select count(*) filter(where status='IN_PRODUCTION') in_production,count(*) filter(where status='BLOCKED') blocked,count(*) filter(where planned_at<now() and status not in('COMPLETED','CLOSED','CANCELLED')) delayed,coalesce(sum(planned_quantity),0) planned,coalesce(sum(produced_quantity),0) produced,coalesce(avg(nullif(real_yield,0)),0) yield,(select count(*) from agro360.production_quality_checks where tenant_id=@TenantId and status='PENDING') quality_pending,(select count(*) from agro360.production_step_records where tenant_id=@TenantId and critical and conformity_status<>'CONFORMING') critical_pending,(select coalesce(sum(quantity),0) from agro360.production_losses where tenant_id=@TenantId) losses,(select coalesce(sum(duration_minutes),0) from agro360.production_stoppages where tenant_id=@TenantId and started_at>=date_trunc('month',now())) stoppage_minutes,(select coalesce(sum(real_cost),0) from agro360.production_costs where tenant_id=@TenantId) real_cost from agro360.production_orders where tenant_id=@TenantId and deleted_at is null", ct);
    public Task<IReadOnlyList<dynamic>> LookupsAsync(string type, CancellationToken ct) { var sql = type switch { "plants" => "select id,name label from agro360.production_industrial_plants where tenant_id=@TenantId and active", "lines" => "select id,name label from agro360.production_lines where tenant_id=@TenantId and active", "centers" => "select id,name label from agro360.production_work_centers where tenant_id=@TenantId and active", "shifts" => "select id,name label from agro360.production_shifts where tenant_id=@TenantId and active", "products" => "select id,name label from agro360.production_products where tenant_id=@TenantId and active", "materials" => "select id,name label from agro360.production_products where tenant_id=@TenantId and active and product_type in('RAW_MATERIAL','SEMI_FINISHED','PACKAGING')", "recipes" => "select v.id,r.name||' · v'||v.version label from agro360.production_recipe_versions v join agro360.production_recipes r on r.tenant_id=v.tenant_id and r.id=v.recipe_id where v.tenant_id=@TenantId and v.status='APPROVED' and r.active", "steps" => "select id,name label from agro360.production_steps where tenant_id=@TenantId and active", "receipts" => "select r.id,r.lot_number||' · disponível '||(r.accepted_quantity-coalesce((select sum(x.quantity) from agro360.production_material_reservations x where x.tenant_id=r.tenant_id and x.receipt_id=r.id and x.status<>'RELEASED'),0))||' '||r.unit label from agro360.production_receipts r where r.tenant_id=@TenantId and r.quality_status in('APPROVED','PARTIALLY_ALLOCATED') and r.accepted_quantity>coalesce((select sum(x.quantity) from agro360.production_material_reservations x where x.tenant_id=r.tenant_id and x.receipt_id=r.id and x.status<>'RELEASED'),0)", "warehouses" => "select id,name label from agro360.inventory_warehouses where tenant_id=@TenantId and active", "reservations" => "select r.id,p.name||' · '||(r.quantity-r.consumed_quantity)||' '||r.unit label from agro360.production_material_reservations r join agro360.production_products p on p.tenant_id=r.tenant_id and p.id=r.material_id where r.tenant_id=@TenantId and r.status in('RESERVED','PARTIALLY_CONSUMED')", "batches" => "select b.id,b.batch_number||' · '||p.name||' · '||b.quantity||' '||b.unit||' · '||b.quality_status label from agro360.production_batches b join agro360.production_products p on p.tenant_id=b.tenant_id and p.id=b.product_id where b.tenant_id=@TenantId and b.deleted_at is null and b.quality_status<>'APPROVED' order by b.created_at desc", "operators" => "select id,name label from agro360.identity_users where tenant_id=@TenantId and status='ACTIVE' and deleted_at is null", _ => throw new DomainException("Consulta auxiliar inválida.", "agro360.production_lookup_invalid") }; return List(sql, ct); }
    public Task<IReadOnlyList<dynamic>> RecipesAsync(ProductionQuery q, CancellationToken ct) => Paged("select r.id,r.code,r.name,p.name product_name,r.active,v.id version_id,v.version,v.status,v.expected_yield,v.valid_until from agro360.production_recipes r join agro360.production_products p on p.tenant_id=r.tenant_id and p.id=r.finished_product_id left join lateral(select * from agro360.production_recipe_versions x where x.tenant_id=r.tenant_id and x.recipe_id=r.id order by version desc limit 1)v on true where r.tenant_id=@TenantId and r.deleted_at is null and (@Search is null or r.name ilike '%'||@Search||'%' or r.code ilike '%'||@Search||'%') and (@Status is null or v.status=@Status) order by r.name", q, ct);
    public Task<Guid> CreateRecipeAsync(RecipeCommand x, CancellationToken ct) => SaveRecipe(null, x, ct);
    public Task<Guid> VersionRecipeAsync(Guid recipeId, RecipeCommand x, CancellationToken ct) => SaveRecipe(recipeId, x, ct);
    private Task<Guid> SaveRecipe(Guid? recipeId, RecipeCommand x, CancellationToken ct) { IndustrialProductionRules.Recipe(x.BaseQuantity, x.ExpectedYield, x.Items.Select(i => (i.MaterialId, i.Quantity, i.Unit))); return Tx(ct, async (c, t) => { var id = recipeId ?? Guid.CreateVersion7(); if (recipeId is null) await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_recipes(id,tenant_id,code,name,finished_product_id,active,created_by,updated_by) values(@Id,@TenantId,@Code,@Name,@Product,true,@UserId,@UserId)", new { Id = id, tenant.TenantId, x.Code, x.Name, Product = x.FinishedProductId, tenant.UserId }, t, cancellationToken: ct)); else if (!await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.production_recipes where tenant_id=@TenantId and id=@Id and active and deleted_at is null)", new { tenant.TenantId, Id = id }, t, cancellationToken: ct))) throw new NotFoundException("Formulação", id); var ver = await c.ExecuteScalarAsync<int>(new CommandDefinition("select coalesce(max(version),0)+1 from agro360.production_recipe_versions where tenant_id=@TenantId and recipe_id=@Id", new { tenant.TenantId, Id = id }, t, cancellationToken: ct)); var vid = Guid.CreateVersion7(); await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_recipe_versions(id,tenant_id,recipe_id,version,base_quantity,unit,expected_yield,expected_loss,instructions,status,technical_responsible_id,valid_from,valid_until,created_by,updated_by) values(@Id,@TenantId,@Recipe,@Version,@BaseQuantity,@Unit,@ExpectedYield,@ExpectedLoss,@Instructions,'DRAFT',@TechnicalResponsibleId,@ValidFrom,@ValidUntil,@UserId,@UserId)", new { Id = vid, tenant.TenantId, Recipe = id, Version = ver, x.BaseQuantity, x.Unit, x.ExpectedYield, x.ExpectedLoss, x.Instructions, x.TechnicalResponsibleId, x.ValidFrom, x.ValidUntil, tenant.UserId }, t, cancellationToken: ct)); foreach (var i in x.Items) await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_recipe_items(id,tenant_id,recipe_version_id,material_id,quantity,unit,loss_percent,created_by,updated_by) values(gen_random_uuid(),@TenantId,@Version,@MaterialId,@Quantity,@Unit,@LossPercent,@UserId,@UserId)", new { tenant.TenantId, Version = vid, i.MaterialId, i.Quantity, i.Unit, i.LossPercent, tenant.UserId }, t, cancellationToken: ct)); foreach (var output in x.Outputs ?? []) { IndustrialProductionRules.Output(output.Quantity, output.Unit, output.OutputType, null, "recipe-output"); await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_recipe_outputs(id,tenant_id,recipe_version_id,product_id,output_type,quantity,unit,created_by,updated_by) values(gen_random_uuid(),@TenantId,@Version,@ProductId,@OutputType,@Quantity,@Unit,@UserId,@UserId)", new { tenant.TenantId, Version = vid, output.ProductId, OutputType = output.OutputType.ToUpperInvariant(), output.Quantity, output.Unit, tenant.UserId }, t, cancellationToken: ct)); } return vid; }); }
    public Task ApproveRecipeAsync(Guid versionId, CancellationToken ct) => Tx(ct, async (c, t) => { var n = await c.ExecuteAsync(new CommandDefinition("update agro360.production_recipe_versions set status='APPROVED',approved_at=now(),approved_by=@UserId,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id and status='DRAFT'", new { tenant.TenantId, tenant.UserId, Id = versionId }, t, cancellationToken: ct)); if (n == 0) throw new ConflictException("Somente versão em rascunho pode ser aprovada; versão aprovada é imutável."); });
    public Task<IReadOnlyList<dynamic>> OrdersAsync(ProductionQuery q, CancellationToken ct) => Paged("select o.*,p.name product_name,l.name line_name from agro360.production_orders o join agro360.production_products p on p.tenant_id=o.tenant_id and p.id=o.finished_product_id join agro360.production_lines l on l.tenant_id=o.tenant_id and l.id=o.line_id where o.tenant_id=@TenantId and o.deleted_at is null and (@Search is null or o.number ilike '%'||@Search||'%' or o.planned_batch ilike '%'||@Search||'%') and (@Status is null or o.status=@Status) and (@LineId is null or o.line_id=@LineId) order by o.planned_at desc", q, ct);
    public Task<dynamic> OrderAsync(Guid id, CancellationToken ct) => One("select o.*,p.name product_name,l.name line_name,u.name responsible_name,coalesce((select sum(r.quantity) from agro360.production_material_reservations r where r.tenant_id=o.tenant_id and r.order_id=o.id and r.status<>'RELEASED'),0) reserved_quantity,coalesce((select sum(r.consumed_quantity) from agro360.production_material_reservations r where r.tenant_id=o.tenant_id and r.order_id=o.id),0) reservation_consumed_quantity,coalesce((select sum(b.quantity) from agro360.production_batches b where b.tenant_id=o.tenant_id and b.order_id=o.id and b.deleted_at is null),0) output_quantity,coalesce((select sum(b.quantity) from agro360.production_batches b where b.tenant_id=o.tenant_id and b.order_id=o.id and b.deleted_at is null and b.quality_status='PENDING'),0) awaiting_quality_quantity,coalesce((select sum(b.quantity) from agro360.production_batches b where b.tenant_id=o.tenant_id and b.order_id=o.id and b.deleted_at is null and b.quality_status='APPROVED'),0) available_quantity,coalesce((select sum(x.quantity) from agro360.production_losses x where x.tenant_id=o.tenant_id and x.order_id=o.id and x.deleted_at is null),0) loss_quantity,(select jsonb_agg(e order by e.created_at) from agro360.production_order_events e where e.tenant_id=o.tenant_id and e.order_id=o.id) history from agro360.production_orders o join agro360.production_products p on p.tenant_id=o.tenant_id and p.id=o.finished_product_id join agro360.production_lines l on l.tenant_id=o.tenant_id and l.id=o.line_id left join agro360.identity_users u on u.tenant_id=o.tenant_id and u.id=o.responsible_id where o.tenant_id=@TenantId and o.id=@Id and o.deleted_at is null", ct, new { Id = id });
    public Task<Guid> CreateOrderAsync(ProductionOrderCommand x, CancellationToken ct) { IndustrialProductionRules.Order(x.FinishedProductId, x.RecipeVersionId, x.PlannedQuantity, x.Unit); return Tx(ct, async (c, t) => { if (!await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.production_recipe_versions v join agro360.production_recipes r on r.tenant_id=v.tenant_id and r.id=v.recipe_id where v.tenant_id=@TenantId and v.id=@Id and v.status='APPROVED' and r.active)", new { tenant.TenantId, Id = x.RecipeVersionId }, t, cancellationToken: ct))) throw new DomainException("Formulação deve estar ativa e aprovada.", "agro360.production_recipe_unavailable"); var id = Guid.CreateVersion7(); var number = $"OP-{DateTime.UtcNow:yyyy}-{await c.ExecuteScalarAsync<long>(new CommandDefinition("select nextval('agro360.production_order_number_seq')", transaction: t, cancellationToken: ct)):000000}"; await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_orders(id,tenant_id,number,plant_id,line_id,finished_product_id,recipe_version_id,planned_batch,planned_quantity,unit,planned_at,priority,responsible_id,demand_origin,sales_order_id,requires_reservation,status,notes,created_by,updated_by) values(@Id,@TenantId,@Number,@PlantId,@LineId,@FinishedProductId,@RecipeVersionId,@PlannedBatch,@PlannedQuantity,@Unit,@PlannedAt,@Priority,@ResponsibleId,@DemandOrigin,@SalesOrderId,@RequiresReservation,'PLANNED',@Notes,@UserId,@UserId);insert into agro360.production_order_events(id,tenant_id,order_id,from_status,to_status,reason,created_by,updated_by) values(gen_random_uuid(),@TenantId,@Id,null,'PLANNED','Ordem criada',@UserId,@UserId)", new { Id = id, tenant.TenantId, Number = number, x.PlantId, x.LineId, x.FinishedProductId, x.RecipeVersionId, x.PlannedBatch, x.PlannedQuantity, x.Unit, x.PlannedAt, x.Priority, x.ResponsibleId, x.DemandOrigin, x.SalesOrderId, x.RequiresReservation, x.Notes, tenant.UserId }, t, cancellationToken: ct)); return id; }); }
    public Task ChangeStatusAsync(Guid id, string status, string? reason, CancellationToken ct) => Tx(ct, async (c, t) => { var o = await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select status,requires_reservation,stock_reserved,exists(select 1 from agro360.production_recipe_items i where i.tenant_id=o.tenant_id and i.recipe_version_id=o.recipe_version_id) has_items,exists(select 1 from agro360.production_step_records r where r.tenant_id=o.tenant_id and r.order_id=o.id and r.status='COMPLETED') has_record,not exists(select 1 from agro360.production_step_records r where r.tenant_id=o.tenant_id and r.order_id=o.id and r.critical and r.status='COMPLETED' and r.conformity_status<>'CONFORMING') critical_complete,exists(select 1 from agro360.production_batches b where b.tenant_id=o.tenant_id and b.order_id=o.id) and not exists(select 1 from agro360.production_batches b where b.tenant_id=o.tenant_id and b.order_id=o.id and b.quality_status<>'APPROVED') quality_approved from agro360.production_orders o where tenant_id=@TenantId and id=@Id for update", new { tenant.TenantId, Id = id }, t, cancellationToken: ct)) ?? throw new NotFoundException("Ordem", id); IndustrialProductionRules.Transition((string)o.status, status.ToUpperInvariant(), reason, (bool)o.has_items, (bool)o.has_record, (bool)o.stock_reserved, (bool)o.requires_reservation, (bool)o.critical_complete, (bool)o.quality_approved); await c.ExecuteAsync(new CommandDefinition("update agro360.production_material_reservations set status='RELEASED',updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and order_id=@Id and @Status='CANCELLED' and status in('RESERVED','PARTIALLY_CONSUMED');update agro360.production_orders set status=@Status,cancel_reason=case when @Status='CANCELLED' then @Reason end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id;insert into agro360.production_order_events(id,tenant_id,order_id,from_status,to_status,reason,created_by,updated_by) values(gen_random_uuid(),@TenantId,@Id,@From,@Status,@Reason,@UserId,@UserId)", new { tenant.TenantId, tenant.UserId, Id = id, From = (string)o.status, Status = status.ToUpperInvariant(), Reason = reason }, t, cancellationToken: ct)); InfrastructureLogMessages.ProductionOrderStatusChanged(log, id, (string)o.status, status); });
    public Task<Guid> ReserveHarvestAsync(HarvestReservationCommand command, CancellationToken ct)
    {
        IndustrialProductionRules.Reservation(command.Quantity, command.Unit, command.IdempotencyKey);
        var hash = Fingerprint(command);
        return Tx(ct, async (c, t) =>
        {
            var replay = await c.QuerySingleOrDefaultAsync<RequestReplay>(new CommandDefinition("select id,request_hash Hash from agro360.production_material_reservations where tenant_id=@TenantId and idempotency_key=@Key", new { tenant.TenantId, Key = command.IdempotencyKey }, t, cancellationToken: ct));
            if (replay is not null) { if (replay.Hash != hash) throw new ConflictException("A chave idempotente já foi usada com outro conteúdo."); return replay.Id; }
            var order = await c.QuerySingleOrDefaultAsync<OrderReservationLookup>(new CommandDefinition("select o.status,o.recipe_version_id RecipeVersionId from agro360.production_orders o where o.tenant_id=@TenantId and o.id=@OrderId and o.deleted_at is null for update", new { tenant.TenantId, command.OrderId }, t, cancellationToken: ct)) ?? throw new NotFoundException("Ordem", command.OrderId);
            if (order.Status is not ("PLANNED" or "AWAITING_MATERIALS" or "RELEASED")) throw new DomainException("O estado da ordem não aceita reservas.", "agro360.production_reservation_state_invalid");
            var source = await c.QuerySingleOrDefaultAsync<HarvestSourceLookup>(new CommandDefinition("select r.accepted_quantity Accepted,r.unit,r.quality_status QualityStatus,r.product_id ProductId,r.warehouse_id WarehouseId,coalesce((select sum(x.quantity) from agro360.production_material_reservations x where x.tenant_id=r.tenant_id and x.receipt_id=r.id and x.status in('RESERVED','PARTIALLY_CONSUMED')),0) Reserved from agro360.production_receipts r where r.tenant_id=@TenantId and r.id=@ReceiptId for update", new { tenant.TenantId, command.ReceiptId }, t, cancellationToken: ct)) ?? throw new NotFoundException("Recebimento", command.ReceiptId);
            if (source.QualityStatus is not ("APPROVED" or "PARTIALLY_ALLOCATED")) throw new DomainException("O recebimento ainda não foi aprovado pela qualidade.", "agro360.production_receipt_quality_pending");
            if (!string.Equals(source.Unit, command.Unit, StringComparison.OrdinalIgnoreCase)) throw new DomainException("A unidade da reserva deve ser igual à unidade recebida; conversão exige fator explícito.", "agro360.production_unit_conversion_required");
            if (command.Quantity > source.Accepted - source.Reserved) throw new ConflictException("Saldo aprovado insuficiente, considerando outras reservas.", "agro360.production_reservation_insufficient");
            var compatible = await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.production_recipe_items i join agro360.production_products p on p.tenant_id=i.tenant_id and p.id=i.material_id where i.tenant_id=@TenantId and i.recipe_version_id=@VersionId and i.material_id=@MaterialId and p.inventory_product_id=@ProductId and upper(i.unit)=upper(@Unit))", new { tenant.TenantId, VersionId = order.RecipeVersionId, command.MaterialId, source.ProductId, command.Unit }, t, cancellationToken: ct));
            if (!compatible) throw new DomainException("Material, produto ou unidade não pertence à versão da formulação.", "agro360.production_material_incompatible");
            var id = Guid.CreateVersion7();
            await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_material_reservations(id,tenant_id,order_id,receipt_id,material_id,warehouse_id,quantity,consumed_quantity,unit,status,idempotency_key,request_hash,created_by,updated_by) values(@Id,@TenantId,@OrderId,@ReceiptId,@MaterialId,@WarehouseId,@Quantity,0,@Unit,'RESERVED',@Key,@Hash,@UserId,@UserId); update agro360.production_orders set stock_reserved=true,status=case when status='AWAITING_MATERIALS' then 'PLANNED' else status end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@OrderId", new { Id = id, tenant.TenantId, command.OrderId, command.ReceiptId, command.MaterialId, source.WarehouseId, command.Quantity, command.Unit, Key = command.IdempotencyKey, Hash = hash, tenant.UserId }, t, cancellationToken: ct));
            return id;
        });
    }

    public Task<Guid> ConsumeReservationAsync(ReservationConsumptionCommand command, CancellationToken ct)
    {
        IndustrialProductionRules.Reservation(command.Quantity, command.Unit, command.IdempotencyKey);
        var hash = Fingerprint(command);
        return Tx(ct, async (c, t) =>
        {
            var replay = await c.QuerySingleOrDefaultAsync<RequestReplay>(new CommandDefinition("select id,request_hash Hash from agro360.production_reservation_consumptions where tenant_id=@TenantId and idempotency_key=@Key", new { tenant.TenantId, Key = command.IdempotencyKey }, t, cancellationToken: ct));
            if (replay is not null) { if (replay.Hash != hash) throw new ConflictException("A chave idempotente já foi usada com outro conteúdo."); return replay.Id; }
            var reservation = await c.QuerySingleOrDefaultAsync<ReservationLookup>(new CommandDefinition("select r.quantity,r.consumed_quantity Consumed,r.unit,r.status,o.status OrderStatus from agro360.production_material_reservations r join agro360.production_orders o on o.tenant_id=r.tenant_id and o.id=r.order_id where r.tenant_id=@TenantId and r.id=@ReservationId and r.order_id=@OrderId for update of r,o", new { tenant.TenantId, command.ReservationId, command.OrderId }, t, cancellationToken: ct)) ?? throw new NotFoundException("Reserva", command.ReservationId);
            if (reservation.OrderStatus is not ("RELEASED" or "IN_PRODUCTION" or "PAUSED")) throw new DomainException("A ordem deve estar liberada ou em produção para consumir.", "agro360.production_consumption_state_invalid");
            if (!string.Equals(reservation.Unit, command.Unit, StringComparison.OrdinalIgnoreCase)) throw new DomainException("Consumo em outra unidade exige conversão explícita.", "agro360.production_unit_conversion_required");
            if (command.Quantity > reservation.Quantity - reservation.Consumed) throw new ConflictException("Consumo excede o saldo reservado.", "agro360.production_consumption_exceeds_reservation");
            var id = Guid.CreateVersion7(); var consumed = reservation.Consumed + command.Quantity;
            await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_reservation_consumptions(id,tenant_id,reservation_id,order_id,quantity,unit,justification,idempotency_key,request_hash,created_by) values(@Id,@TenantId,@ReservationId,@OrderId,@Quantity,@Unit,@Justification,@Key,@Hash,@UserId); update agro360.production_material_reservations set consumed_quantity=@Consumed,status=case when @Consumed=quantity then 'CONSUMED' else 'PARTIALLY_CONSUMED' end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@ReservationId; update agro360.production_orders set consumed_quantity=consumed_quantity+@Quantity,status=case when status='RELEASED' then 'IN_PRODUCTION' else status end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@OrderId", new { Id = id, tenant.TenantId, command.ReservationId, command.OrderId, command.Quantity, command.Unit, command.Justification, Key = command.IdempotencyKey, Hash = hash, Consumed = consumed, tenant.UserId }, t, cancellationToken: ct));
            return id;
        });
    }

    public Task<Guid> RegisterOutputAsync(ProductionOutputCommand command, CancellationToken ct)
    {
        IndustrialProductionRules.Output(command.Quantity, command.Unit, command.OutputType, command.Reason, command.IdempotencyKey);
        var hash = Fingerprint(command); var type = command.OutputType.ToUpperInvariant();
        return Tx(ct, async (c, t) =>
        {
            var replay = await c.QuerySingleOrDefaultAsync<RequestReplay>(new CommandDefinition("select id,request_hash Hash from agro360.production_output_requests where tenant_id=@TenantId and idempotency_key=@Key", new { tenant.TenantId, Key = command.IdempotencyKey }, t, cancellationToken: ct));
            if (replay is not null) { if (replay.Hash != hash) throw new ConflictException("A chave idempotente já foi usada com outro conteúdo."); return replay.Id; }
            var status = await c.ExecuteScalarAsync<string?>(new CommandDefinition("select status from agro360.production_orders where tenant_id=@TenantId and id=@OrderId and deleted_at is null for update", new { tenant.TenantId, command.OrderId }, t, cancellationToken: ct)) ?? throw new NotFoundException("Ordem", command.OrderId);
            if (status is not ("IN_PRODUCTION" or "PAUSED")) throw new DomainException("Resultados somente podem ser apontados durante a produção.", "agro360.production_output_state_invalid"); var expected = await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.production_orders o left join agro360.production_recipe_outputs ro on ro.tenant_id=o.tenant_id and ro.recipe_version_id=o.recipe_version_id and ro.product_id=@ProductId and ro.output_type=@Type and upper(ro.unit)=upper(@Unit) where o.tenant_id=@TenantId and o.id=@OrderId and ((@Type='MAIN' and o.finished_product_id=@ProductId and upper(o.unit)=upper(@Unit)) or (@Type='COPRODUCT' and ro.id is not null) or @Type in('LOSS','SCRAP'))) ", new { tenant.TenantId, command.OrderId, command.ProductId, Type = type, command.Unit }, t, cancellationToken: ct)); if (!expected) throw new DomainException("O resultado não pertence à versão da formulação ou usa unidade incompatível.", "agro360.production_output_incompatible");
            var id = Guid.CreateVersion7(); Guid? batchId = null;
            if (type is "MAIN" or "COPRODUCT") { batchId = Guid.CreateVersion7(); await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_batches(id,tenant_id,order_id,product_id,batch_number,quantity,unit,manufactured_at,expires_on,quality_status,warehouse_id,output_type,created_by,updated_by) values(@BatchId,@TenantId,@OrderId,@ProductId,@Batch,@Quantity,@Unit,@At,@Expires,'PENDING',@WarehouseId,@Type,@UserId,@UserId); insert into agro360.production_output_requests(id,tenant_id,order_id,batch_id,output_type,quantity,unit,idempotency_key,request_hash,created_by) values(@Id,@TenantId,@OrderId,@BatchId,@Type,@Quantity,@Unit,@Key,@Hash,@UserId); insert into agro360.production_batch_traceability(id,tenant_id,batch_id,relation_type,source_batch,source_entity,source_id,source_reference,metadata,created_by,updated_by) select gen_random_uuid(),r.tenant_id,@BatchId,'RECEIPT',pr.lot_number,'production_receipts',r.receipt_id,pr.lot_number,jsonb_build_object('reserved_quantity',r.quantity,'consumed_quantity',r.consumed_quantity,'unit',r.unit),@UserId,@UserId from agro360.production_material_reservations r join agro360.production_receipts pr on pr.tenant_id=r.tenant_id and pr.id=r.receipt_id where r.tenant_id=@TenantId and r.order_id=@OrderId and r.consumed_quantity>0", new { Id = id, BatchId = batchId, tenant.TenantId, command.OrderId, command.ProductId, command.WarehouseId, Batch = command.BatchNumber, command.Quantity, command.Unit, At = command.ManufacturedAt, Expires = command.ExpiresOn, Type = type, Key = command.IdempotencyKey, Hash = hash, tenant.UserId }, t, cancellationToken: ct)); }
            else { await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_losses(id,tenant_id,order_id,loss_type,quantity,unit,reason,responsible_id,created_by,updated_by) values(@LossId,@TenantId,@OrderId,case when @Type='LOSS' then 'TECHNICAL' else 'SCRAP' end,@Quantity,@Unit,@Reason,@UserId,@UserId,@UserId); insert into agro360.production_output_requests(id,tenant_id,order_id,output_type,quantity,unit,idempotency_key,request_hash,created_by) values(@Id,@TenantId,@OrderId,@Type,@Quantity,@Unit,@Key,@Hash,@UserId)", new { LossId = Guid.CreateVersion7(), Id = id, tenant.TenantId, command.OrderId, Type = type, command.Quantity, command.Unit, command.Reason, Key = command.IdempotencyKey, Hash = hash, tenant.UserId }, t, cancellationToken: ct)); }
            return id;
        });
    }

    public Task<dynamic> CostsAsync(Guid orderId, CancellationToken ct) => One("select o.id order_id,o.number,coalesce(c.planned_cost,0) planned_cost,c.real_cost,c.material_cost,c.loss_cost,c.labor_cost,c.machine_cost,c.unit_cost,c.real_cost is null costs_pending,'RECORDED_COST' allocation_basis from agro360.production_orders o left join lateral(select sum(real_cost) real_cost,sum(material_cost) material_cost,sum(loss_cost) loss_cost,sum(labor_cost) labor_cost,sum(machine_cost) machine_cost,sum(planned_cost) planned_cost,case when sum(b.quantity)>0 then round(sum(real_cost)/sum(b.quantity),6) end unit_cost from agro360.production_costs x left join agro360.production_batches b on b.tenant_id=x.tenant_id and b.id=x.batch_id where x.tenant_id=o.tenant_id and x.order_id=o.id and x.deleted_at is null)c on true where o.tenant_id=@TenantId and o.id=@Id and o.deleted_at is null", ct, new { Id = orderId });

    public Task<Guid> RecordAsync(ProductionRecordCommand x, CancellationToken ct)
    {
        IndustrialProductionRules.Record(x.OperatorId, x.Produced, x.Consumed, x.Loss, x.LossReason);
        if (x.EndedAt < x.StartedAt) throw new DomainException("Fim deve ser posterior ao início.", "agro360.production_period_invalid");
        return Tx(ct, async (c, t) =>
        {
            var order = await c.QuerySingleOrDefaultAsync<(string Status, Guid LineId)>(new CommandDefinition(
                "select status,line_id LineId from agro360.production_orders where tenant_id=@TenantId and id=@OrderId and deleted_at is null for update",
                new { tenant.TenantId, x.OrderId }, t, cancellationToken: ct));
            if (order == default) throw new NotFoundException("Ordem", x.OrderId);
            if (order.Status is not ("RELEASED" or "IN_PRODUCTION" or "PAUSED"))
                throw new DomainException("O estado atual da ordem não aceita apontamentos.", "agro360.production_order_record_forbidden");
            if (order.LineId != x.LineId)
                throw new DomainException("A linha informada não pertence à ordem.", "agro360.production_line_mismatch");
            if (!await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.identity_users where tenant_id=@TenantId and id=@OperatorId and status='ACTIVE' and deleted_at is null)", new { tenant.TenantId, x.OperatorId }, t, cancellationToken: ct)))
                throw new DomainException("Operador inexistente ou inativo.", "agro360.production_operator_unavailable");

            var step = await c.QuerySingleOrDefaultAsync<ProductionStepLookup>(new CommandDefinition(
                "select id,critical,minimum_minutes MinimumMinutes,minimum_temperature MinimumTemperature,maximum_temperature MaximumTemperature,requires_evidence RequiresEvidence from agro360.production_steps where tenant_id=@TenantId and id=@Step and active and deleted_at is null",
                new { tenant.TenantId, Step = x.StepId }, t, cancellationToken: ct));
            if (step is null) throw new NotFoundException("Etapa", x.StepId);
            var duration = (x.EndedAt - x.StartedAt).TotalMinutes;
            var criteriaConfigured = step.MinimumMinutes is not null || step.MinimumTemperature is not null || step.MaximumTemperature is not null || step.RequiresEvidence;
            var conforming = (!step.MinimumMinutes.HasValue || duration >= step.MinimumMinutes.Value)
                && (!step.MinimumTemperature.HasValue || x.Temperature >= step.MinimumTemperature.Value)
                && (!step.MaximumTemperature.HasValue || x.Temperature <= step.MaximumTemperature.Value)
                && (!step.RequiresEvidence || !string.IsNullOrWhiteSpace(x.EvidenceReference));
            if ((step.MinimumTemperature.HasValue || step.MaximumTemperature.HasValue) && x.Temperature is null)
                throw new DomainException("A etapa exige medição de temperatura.", "agro360.production_temperature_required");
            var conformity = step.Critical && !criteriaConfigured ? "PENDING" : conforming ? "CONFORMING" : "NON_CONFORMING";

            var id = Guid.CreateVersion7();
            await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_step_records(id,tenant_id,order_id,step_id,operator_id,line_id,started_at,ended_at,produced_quantity,consumed_quantity,loss_quantity,scrap_quantity,loss_reason,notes,input_batch,output_batch,temperature,evidence_reference,critical,conformity_status,status,created_by,updated_by) values(@Id,@TenantId,@OrderId,@StepId,@OperatorId,@LineId,@StartedAt,@EndedAt,@Produced,@Consumed,@Loss,@Scrap,@LossReason,@Notes,@InputBatch,@OutputBatch,@Temperature,@EvidenceReference,@Critical,@Conformity,'COMPLETED',@UserId,@UserId);update agro360.production_orders set produced_quantity=produced_quantity+@Produced,consumed_quantity=consumed_quantity+@Consumed,real_yield=case when consumed_quantity+@Consumed>0 then (produced_quantity+@Produced)/(consumed_quantity+@Consumed)*100 else 0 end,status=case when status='RELEASED' then 'IN_PRODUCTION' else status end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@OrderId and status in('RELEASED','IN_PRODUCTION','PAUSED')", new { Id = id, tenant.TenantId, x.OrderId, x.StepId, x.OperatorId, x.LineId, x.StartedAt, x.EndedAt, x.Produced, x.Consumed, x.Loss, x.Scrap, x.LossReason, x.Notes, x.InputBatch, x.OutputBatch, x.Temperature, x.EvidenceReference, Critical = step.Critical, Conformity = conformity, tenant.UserId }, t, cancellationToken: ct));
            return id;
        });
    }

    public Task<Guid> ConsumeAsync(MaterialConsumptionCommand command, CancellationToken ct) { if (command.Quantity <= 0) throw new DomainException("Consumo deve ser positivo.", "agro360.production_consumption_invalid"); if (command.ExpiredOverride && string.IsNullOrWhiteSpace(command.Justification)) throw new DomainException("Lote vencido exige permissão e justificativa.", "agro360.production_expired_justification_required"); return Tx(ct, async (c, t) => { var lot = await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select quantity quantity_available,expires_on,quality_status from agro360.inventory_stock_lots where tenant_id=@TenantId and id=@Id for update", new { tenant.TenantId, Id = command.StockLotId }, t, cancellationToken: ct)) ?? throw new NotFoundException("Lote de estoque", command.StockLotId); if ((decimal)lot.quantity_available < command.Quantity) throw new DomainException("Consumo maior que o estoque disponível.", "agro360.production_insufficient_stock"); if ((string)lot.quality_status == "BLOCKED") throw new DomainException("Lote bloqueado pela qualidade não pode ser consumido.", "agro360.production_batch_blocked"); if ((DateOnly?)lot.expires_on < DateOnly.FromDateTime(DateTime.UtcNow) && !command.ExpiredOverride) throw new DomainException("Lote vencido não pode ser consumido.", "agro360.production_batch_expired"); var id = Guid.CreateVersion7(); await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_material_consumptions(id,tenant_id,order_id,material_id,stock_lot_id,quantity,unit,justification,status,created_by,updated_by) values(@Id,@TenantId,@OrderId,@MaterialId,@StockLotId,@Quantity,@Unit,@Justification,'POSTED',@UserId,@UserId);update agro360.inventory_stock_lots set quantity=quantity-@Quantity where tenant_id=@TenantId and id=@StockLotId", new { Id = id, tenant.TenantId, command.OrderId, command.MaterialId, command.StockLotId, command.Quantity, command.Unit, command.Justification, tenant.UserId }, t, cancellationToken: ct)); return id; }); }
    public Task<Guid> QualityAsync(QualityDecisionCommand x, CancellationToken ct) { var result = IndustrialProductionRules.QualityDecision(x.Result, x.Reason, x.ReportReference, x.EvidenceReference); return Tx(ct, async (c, t) => { var batch = await c.QuerySingleOrDefaultAsync<ProductionBatchLookup>(new CommandDefinition("select b.id,b.quality_status QualityStatus,b.quantity,b.unit,b.batch_number BatchNumber,b.warehouse_id WarehouseId,b.expires_on ExpiresOn,p.inventory_product_id InventoryProductId from agro360.production_batches b join agro360.production_products p on p.tenant_id=b.tenant_id and p.id=b.product_id where b.tenant_id=@TenantId and b.id=@BatchId and b.order_id=@OrderId and b.deleted_at is null for update of b", new { tenant.TenantId, x.BatchId, x.OrderId }, t, cancellationToken: ct)); if (batch is null) throw new NotFoundException("Lote de produção", x.BatchId); var id = Guid.CreateVersion7(); await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_quality_checks(id,tenant_id,order_id,batch_id,step_id,status,reason,report_reference,evidence_reference,mandatory,decided_at,decided_by,created_by,updated_by) values(@Id,@TenantId,@OrderId,@BatchId,@StepId,@Status,@Reason,@Report,@Evidence,true,now(),@UserId,@UserId,@UserId);update agro360.production_batches set quality_status=@Status,released_at=case when @Status='APPROVED' then now() else released_at end,released_by=case when @Status='APPROVED' then @UserId else released_by end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@BatchId and order_id=@OrderId;update agro360.production_orders set status=case when @Status in('REJECTED','BLOCKED') then 'BLOCKED' else status end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@OrderId", new { Id = id, tenant.TenantId, x.OrderId, x.BatchId, x.StepId, Status = result, x.Reason, Report = x.ReportReference, Evidence = x.EvidenceReference, tenant.UserId }, t, cancellationToken: ct)); if (result == "APPROVED") { if (batch.QualityStatus == "APPROVED") throw new ConflictException("O lote já foi liberado.", "agro360.production_batch_already_released"); if (batch.WarehouseId is null || batch.InventoryProductId is null) throw new DomainException("Produto e depósito de estoque devem estar vinculados antes da liberação.", "agro360.production_output_stock_mapping_required"); var balance = await c.QuerySingleOrDefaultAsync<BalanceLookup>(new CommandDefinition("select id,available,average_cost AverageCost,version from agro360.inventory_stock_balances where tenant_id=@TenantId and warehouse_id=@WarehouseId and product_id=@ProductId for update", new { tenant.TenantId, WarehouseId = batch.WarehouseId, ProductId = batch.InventoryProductId }, t, cancellationToken: ct)); var after = (balance?.Available ?? 0) + batch.Quantity; var version = (balance?.Version ?? 0) + 1; await c.ExecuteAsync(new CommandDefinition("insert into agro360.inventory_stock_lots(id,tenant_id,warehouse_id,product_id,lot_number,expires_on,quantity,quality_status) values(gen_random_uuid(),@TenantId,@WarehouseId,@ProductId,@Batch,@ExpiresOn,@Quantity,'APPROVED'); insert into agro360.inventory_stock_balances(id,tenant_id,warehouse_id,product_id,unit,available,reserved,minimum,average_cost,version) values(@BalanceId,@TenantId,@WarehouseId,@ProductId,@Unit,@After,0,0,@AverageCost,@Version) on conflict(tenant_id,warehouse_id,product_id) do update set available=@After,updated_at=now(),version=@Version; insert into agro360.inventory_stock_movements(id,tenant_id,warehouse_id,product_id,movement_type,quantity,unit,lot_number,reference_type,reference_id,notes,idempotency_key,balance_after,average_cost_after,balance_version,occurred_at,created_by) values(gen_random_uuid(),@TenantId,@WarehouseId,@ProductId,'PRODUCTION',@Quantity,@Unit,@Batch,'PRODUCTION_BATCH',@BatchId,'Liberação pela qualidade final',@MovementKey,@After,@AverageCost,@Version,now(),@UserId)", new { tenant.TenantId, WarehouseId = batch.WarehouseId, ProductId = batch.InventoryProductId, Batch = batch.BatchNumber, batch.ExpiresOn, batch.Quantity, batch.Unit, BalanceId = balance?.Id ?? Guid.CreateVersion7(), After = after, AverageCost = balance?.AverageCost ?? 0, Version = version, BatchId = batch.Id, MovementKey = $"production-batch:{batch.Id:N}", tenant.UserId }, t, cancellationToken: ct)); } return id; }); }
    public Task<Guid> StopAsync(StoppageCommand x, CancellationToken ct) { if (string.IsNullOrWhiteSpace(x.Reason) || x.EndedAt <= x.StartedAt) throw new DomainException("Parada exige motivo e período válido.", "agro360.production_stoppage_invalid"); return Tx(ct, async (c, t) => { var id = Guid.CreateVersion7(); await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_stoppages(id,tenant_id,line_id,order_id,equipment_id,type,reason,critical,started_at,ended_at,duration_minutes,responsible_id,estimated_impact,corrective_action,status,created_by,updated_by) values(@Id,@TenantId,@LineId,@OrderId,@EquipmentId,@Type,@Reason,@Critical,@StartedAt,@EndedAt,@Minutes,@ResponsibleId,@EstimatedImpact,@CorrectiveAction,'COMPLETED',@UserId,@UserId)", new { Id = id, tenant.TenantId, x.LineId, x.OrderId, x.EquipmentId, x.Type, x.Reason, x.Critical, x.StartedAt, x.EndedAt, Minutes = (int)(x.EndedAt - x.StartedAt).TotalMinutes, x.ResponsibleId, x.EstimatedImpact, x.CorrectiveAction, tenant.UserId }, t, cancellationToken: ct)); return id; }); }
    public Task<IReadOnlyList<dynamic>> TraceAsync(string batch, CancellationToken ct) => List("select b.batch_number,b.quality_status,o.number order_number,p.name product_name,t.relation_type,t.source_batch,t.source_entity,t.source_reference,t.created_at from agro360.production_batches b join agro360.production_orders o on o.tenant_id=b.tenant_id and o.id=b.order_id join agro360.production_products p on p.tenant_id=b.tenant_id and p.id=b.product_id left join agro360.production_batch_traceability t on t.tenant_id=b.tenant_id and t.batch_id=b.id where b.tenant_id=@TenantId and b.batch_number=@Batch order by t.created_at", ct, new { Batch = batch });
    public async Task<byte[]> ExportAsync(string report, ProductionQuery q, CancellationToken ct) { var rows = report switch { "orders" => await OrdersAsync(q, ct), "recipes" => await RecipesAsync(q, ct), _ => throw new DomainException("Relatório inválido.", "agro360.production_report_invalid") }; var s = new StringBuilder("sep=;\n"); s.AppendLine(report == "orders" ? "Número;Produto;Linha;Planejado;Produzido;Rendimento;Status" : "Código;Formulação;Produto;Versão;Rendimento;Status"); foreach (var r in rows) s.AppendLine(report == "orders" ? $"{r.number};{r.product_name};{r.line_name};{r.planned_quantity};{r.produced_quantity};{r.real_yield};{r.status}" : $"{r.code};{r.name};{r.product_name};{r.version};{r.expected_yield};{r.status}"); return Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(s.ToString())).ToArray(); }
    private Task<T> Tx<T>(CancellationToken ct, Func<Npgsql.NpgsqlConnection, Npgsql.NpgsqlTransaction, Task<T>> operation) => db.InTenantTransactionAsync(operation, ct); private Task Tx(CancellationToken ct, Func<Npgsql.NpgsqlConnection, Npgsql.NpgsqlTransaction, Task> operation) => db.InTenantTransactionAsync(operation, ct);
    private Task<dynamic> One(string sql, CancellationToken ct, object? extra = null) => db.InTenantTransactionAsync<dynamic>(async (c, t) => { var p = new DynamicParameters(extra); p.Add("TenantId", tenant.TenantId); return await c.QuerySingleOrDefaultAsync(new CommandDefinition(sql, p, t, cancellationToken: ct)) ?? throw new NotFoundException("Produção", Guid.Empty); }, ct);
    private Task<IReadOnlyList<dynamic>> List(string sql, CancellationToken ct, object? extra = null) => db.InTenantTransactionAsync<IReadOnlyList<dynamic>>(async (c, t) => { var p = new DynamicParameters(extra); p.Add("TenantId", tenant.TenantId); return (await c.QueryAsync(new CommandDefinition(sql, p, t, cancellationToken: ct))).AsList(); }, ct);
    private Task<IReadOnlyList<dynamic>> Paged(string sql, ProductionQuery q, CancellationToken ct) => db.InTenantTransactionAsync<IReadOnlyList<dynamic>>(async (c, t) => (await c.QueryAsync(new CommandDefinition(sql + " limit @Take offset @Skip", new { tenant.TenantId, Search = string.IsNullOrWhiteSpace(q.Search) ? null : q.Search, Status = string.IsNullOrWhiteSpace(q.Status) ? null : q.Status, q.LineId, Take = Math.Clamp(q.PageSize, 1, 100), Skip = (Math.Max(1, q.Page) - 1) * Math.Clamp(q.PageSize, 1, 100) }, t, cancellationToken: ct))).AsList(), ct);
    private static string Fingerprint<T>(T value) => Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(value))).ToLowerInvariant();
    private sealed record RequestReplay(Guid Id, string Hash);
    private sealed record OrderReservationLookup(string Status, Guid RecipeVersionId);
    private sealed record HarvestSourceLookup(decimal Accepted, string Unit, string QualityStatus, Guid ProductId, Guid WarehouseId, decimal Reserved);
    private sealed record ReservationLookup(decimal Quantity, decimal Consumed, string Unit, string Status, string OrderStatus);
    private sealed class ProductionStepLookup { public Guid Id { get; init; } public bool Critical { get; init; } public int? MinimumMinutes { get; init; } public decimal? MinimumTemperature { get; init; } public decimal? MaximumTemperature { get; init; } public bool RequiresEvidence { get; init; } }
    private sealed class ProductionBatchLookup { public Guid Id { get; init; } public string QualityStatus { get; init; } = string.Empty; public decimal Quantity { get; init; } public string Unit { get; init; } = string.Empty; public string BatchNumber { get; init; } = string.Empty; public Guid? WarehouseId { get; init; } public DateOnly? ExpiresOn { get; init; } public Guid? InventoryProductId { get; init; } }
    private sealed record BalanceLookup(Guid Id, decimal Available, decimal AverageCost, long Version);
}
